mapper.select:
SELECT opr_hstry_sn , opr_ymd , ownr_nm , oprtr_id , CAST(AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) AS oprtr_nm , rfid_no , rq_bk_tm , actl_bk_tm , frst_tm , last_tm , opr_schdl , tdrvg_dstnc , reg_dt , mdfcn_dt FROM anls_opr_hstry WHERE 1 = 1 AND opr_ymd BETWEEN #{startDate} AND #{endDate}
AND CAST(AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) LIKE CONCAT('%', #{oprtrNm}, '%')
AND ownr_nm IN
#{ownr}
and ownr_nm = #{ownrNm}
ORDER BY opr_ymd DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

    	SELECT COUNT(*)
		FROM anls_opr_hstry
		WHERE 1 = 1
			AND opr_ymd BETWEEN #{startDate} AND #{endDate}

   			AND CAST(AES_DECRYPT(FROM_BASE64(oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) LIKE CONCAT('%', #{oprtrNm}, '%')


   	        AND ownr_nm IN

   	            #{ownr}





    	    	and ownr_nm = #{ownrNm}

SELECT -- h.opr_hstry_sn, h.opr_ymd AS `운행 일자`, h.ownr_nm AS `운수 회사`, -- h.oprtr_id, CAST(AES_DECRYPT(FROM_BASE64(h.oprtr_nm), 'theimc') AS CHAR(100) CHARACTER SET UTF8MB4) AS `운전원 성명`, -- h.rfid_no, -- h.rq_bk_tm, -- h.actl_bk_tm, h.frst_tm AS `승무 개시시간`, h.last_tm AS `승무 종료시간`, IFNULL(jt.회차, '') AS `회차`, IFNULL(jt.기점, '') AS `기점`, IFNULL(jt.종점, '') AS `종점`, -- IFNULL(jt.노선순번, '') AS `노선순번`, -- IFNULL(jt.차량순번, '') AS `차량순번`, IFNULL(jt.기점출발, '') AS `기점출발`, IFNULL(jt.종점도착, '') AS `종점도착`, IFNULL(jt.소요시간1, '') AS `소요시간1`, IFNULL(jt.종점출발, '') AS `종점출발`, IFNULL(jt.기점도착, '') AS `기점도착`, IFNULL(jt.소요시간2, '') AS `소요시간2`, IFNULL(jt.노선명, '') AS `노선명`, IFNULL(jt.차량번호, '') AS `차량번호` FROM anls_opr_hstry AS h JOIN JSON_TABLE( h.opr_schdl, '$[*]' COLUMNS ( 회차 INT PATH '$.회차', 기점 VARCHAR(50) PATH '$.기점', 종점 VARCHAR(50) PATH '$.종점', 차량번호 VARCHAR(50) PATH '$.차량번호', 노선명 VARCHAR(100) PATH '$.노선명', 노선순번 INT PATH '$.노선순번', 차량순번 INT PATH '$.차량순번', 기점출발 TIME PATH '$.기점출발', 종점도착 TIME PATH '$.종점도착', 종점출발 TIME PATH '$.종점출발', 기점도착 TIME PATH '$.기점도착', 소요시간1 INT PATH '$.소요시간1', 소요시간2 INT PATH '$.소요시간2' ) ) AS jt WHERE 1 = 1 AND h.opr_hstry_sn IN
#{oprLstrySn}
AND h.ownr_nm IN
#{ownr}
and h.ownr_nm = #{ownrNm}
ORDER BY h.opr_ymd DESC, h.opr_hstry_sn DESC, jt.회차 ASC
